#!/usr/bin/env python3
"""buildr.py - a tiny make-like build tool driven by build.json.

Each rule has:
  - target: a file the rule produces
  - sources: list of input files (may include targets of other rules)
  - cmd: shell command that (re)builds the target

A rule is *stale* (must run) if its target is missing or older than any
source (by mtime). Staleness propagates along the dependency graph: if a
dependency rebuilds, everything downstream of it rebuilds too.

Options:
  -j N        run up to N independent ready rules concurrently
  --dry-run   print what would run (in dependency order) without running
"""

import argparse
import json
import os
import subprocess
import sys
import threading
from collections import deque
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait


class BuildError(Exception):
    pass


def load_config(path):
    with open(path, "r", encoding="utf-8") as fh:
        cfg = json.load(fh)
    rules = cfg.get("rules") if isinstance(cfg, dict) else cfg
    if not isinstance(rules, list):
        raise BuildError("config must contain a list of rules")
    seen = {}
    for i, r in enumerate(rules):
        for key in ("target", "sources", "cmd"):
            if key not in r:
                raise BuildError(f"rule #{i} is missing '{key}'")
        if not isinstance(r["sources"], list):
            raise BuildError(f"rule #{i} ('{r['target']}'): 'sources' must be a list")
        if r["target"] in seen:
            raise BuildError(f"duplicate target '{r['target']}'")
        seen[r["target"]] = i
    return rules


def build_graph(rules):
    """Return (deps, rdeps): rule index -> indices it depends on / dependents."""
    by_target = {r["target"]: i for i, r in enumerate(rules)}
    deps, rdeps = [], [set() for _ in rules]
    for i, r in enumerate(rules):
        d = set()
        for src in r["sources"]:
            j = by_target.get(src)
            if j is not None:
                if j == i:
                    raise BuildError(f"rule '{r['target']}' depends on itself")
                d.add(j)
                rdeps[j].add(i)
        deps.append(d)
    return deps, rdeps


def topo_order(rules, deps, rdeps):
    """Kahn topological order; raises BuildError on cycles."""
    indeg = [len(d) for d in deps]
    order, queue = [], deque(i for i, k in enumerate(indeg) if k == 0)
    while queue:
        i = queue.popleft()
        order.append(i)
        for j in rdeps[i]:
            indeg[j] -= 1
            if indeg[j] == 0:
                queue.append(j)
    if len(order) != len(rules):
        cyclic = sorted(rules[i]["target"] for i in range(len(rules)) if indeg[i] > 0)
        raise BuildError("dependency cycle detected involving: " + ", ".join(cyclic))
    return order


def is_stale(rule):
    target = rule["target"]
    if not os.path.exists(target):
        return True
    tmtime = os.path.getmtime(target)
    for src in rule["sources"]:
        if not os.path.exists(src) or os.path.getmtime(src) > tmtime:
            return True
    return False


def compute_dirty(rules, order, deps):
    """Static staleness + propagation through the graph (topo order)."""
    dirty = [False] * len(rules)
    for i in order:
        dirty[i] = is_stale(rules[i]) or any(dirty[d] for d in deps[i])
    return dirty


def plan(rules, dirty):
    return [i for i in dirty_order if True] if False else [i for i, d in enumerate(dirty) if d]


def run_rule(rule):
    proc = subprocess.run(rule["cmd"], shell=True)
    if proc.returncode != 0:
        raise BuildError(
            f"command for target '{rule['target']}' failed with exit code {proc.returncode}"
        )


def execute_parallel(rules, todo, deps, rdeps, jobs, dry_run=False, verbose=False):
    dirty_set = set(todo)
    if dry_run:
        for i in sorted(todo, key=lambda x: topo_pos[x]):
            print(f"[dry-run] would run: {rules[i]['target']}: {rules[i]['cmd']}")
        return True

    pending = {i: len(deps[i] & dirty_set) for i in todo}
    dependents = {i: [j for j in rdeps[i] if j in dirty_set] for i in todo}
    queue = deque(sorted((i for i in todo if pending[i] == 0), key=lambda x: topo_pos[x]))
    lock = threading.Lock()
    cv = threading.Condition(lock)
    state = {"error": None, "remaining": len(todo)}

    def report(msg):
        print(msg, flush=True)

    def worker(i):
        rule = rules[i]
        if verbose:
            report(f"[buildr] RUN  {rule['target']}")
        try:
            run_rule(rule)
        except Exception as exc:  # noqa: BLE001 - surface any failure
            with cv:
                if state["error"] is None:
                    state["error"] = exc
                state["remaining"] -= 1
                cv.notify_all()
            return
        with cv:
            state["remaining"] -= 1
            for j in dependents[i]:
                pending[j] -= 1
                if pending[j] == 0:
                    queue.append(j)
            cv.notify_all()

    if not todo:
        return True
    with ThreadPoolExecutor(max_workers=min(jobs, len(todo))) as pool:
        futures = set()
        with cv:
            while queue:
                futures.add(pool.submit(worker, queue.popleft()))
        while futures:
            done, futures = wait(futures, return_when=FIRST_COMPLETED)
            for _ in done:
                pass
            with cv:
                if state["error"] is not None and not queue:
                    break
                while queue:
                    futures.add(pool.submit(worker, queue.popleft()))
    if state["error"] is not None:
        raise state["error"]
    if state["remaining"] != 0:
        raise BuildError("internal scheduling error: not all rules completed")
    return True


# position of every rule in topological order, for deterministic-ish dispatch
topo_pos = {}


def main(argv=None):
    global topo_pos
    parser = argparse.ArgumentParser(prog="buildr", description="tiny make-like builder")
    parser.add_argument("-f", "--file", default="build.json", help="build configuration")
    parser.add_argument("-j", "--jobs", type=int, default=1, help="parallel jobs")
    parser.add_argument("--dry-run", action="store_true", help="print what would run")
    parser.add_argument("-v", "--verbose", action="store_true", help="verbose output")
    args = parser.parse_args(argv)

    try:
        rules = load_config(args.file)
        deps, rdeps = build_graph(rules)
        order = topo_order(rules, deps, rdeps)
        topo_pos = {i: pos for pos, i in enumerate(order)}
        dirty = compute_dirty(rules, order, deps)
        todo = [i for i in order if dirty[i]]

        if args.verbose:
            for i in order:
                tag = "STALE" if dirty[i] else "fresh"
                print(f"[buildr] {tag:5} {rules[i]['target']}", flush=True)

        if not todo:
            print("[buildr] nothing to do", flush=True)
            return 0
        if args.dry_run:
            execute_parallel(rules, todo, deps, rdeps, args.jobs, dry_run=True)
            print(f"[buildr] dry-run: {len(todo)} rule(s) would run", flush=True)
            return 0
        execute_parallel(rules, todo, deps, rdeps, args.jobs, verbose=args.verbose)
        print(f"[buildr] built {len(todo)} rule(s)", flush=True)
        return 0
    except BuildError as exc:
        print(f"[buildr] error: {exc}", file=sys.stderr, flush=True)
        return 1


if __name__ == "__main__":
    sys.exit(main())

